/**
 * Anti-Corruption: respuesta MikroTik → contrato API
 * { success, result: { status, question?, diagnostic? }, error }
 * docs/spec/04_N8N_WORKFLOW_SPEC.md §10 / fixtures §11
 */
function unwrap(raw) {
  if (Array.isArray(raw)) return raw[0] || {};
  if (raw && Array.isArray(raw.body)) return raw.body[0] || {};
  if (raw && raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body)) {
    // HTTP node a veces anida el JSON bajo body
    if (raw.body.success !== undefined || raw.body.workflow || raw.body.instruction) return raw.body;
  }
  return raw || {};
}

const incoming = $input.first()?.json || {};
const statusCode = Number(incoming.statusCode || incoming.error?.httpCode || 0);
const errMsg = String(incoming.error?.message || incoming.message || '');
const looksValidation = /VALIDATION_ERROR|Faltan campos|400 -/.test(errMsg);

const isHttpError = statusCode >= 400 || (incoming.error && typeof incoming.error === 'object');

if (isHttpError) {
  const isTimeout = /timeout|ETIMEDOUT|ECONNABORTED/i.test(errMsg);
  const isValidation = looksValidation || (statusCode >= 400 && statusCode < 500 && statusCode !== 408);
  return [{
    json: {
      success: false,
      result: null,
      error: {
        type: isTimeout ? 'TIMEOUT' : (isValidation ? 'VALIDATION_ERROR' : 'EXTERNAL_SERVICE_ERROR'),
        message: errMsg || (isValidation ? 'diagnostic service rejected input' : 'diagnostic service unreachable'),
        retryable: !isValidation,
      },
    },
  }];
}

const payload = unwrap(incoming);

// Ya viene en forma de contrato (status WAITING_USER/COMPLETED/ESCALATED)
const directStatus = typeof payload.status === 'string' ? payload.status.toUpperCase() : '';
if (['WAITING_USER', 'COMPLETED', 'ESCALATED'].includes(directStatus) && !payload.workflow) {
  return [{
    json: {
      success: true,
      result: {
        status: directStatus,
        ...(payload.question !== undefined ? { question: payload.question } : {}),
        ...(payload.diagnostic !== undefined
          ? { diagnostic: typeof payload.diagnostic === 'string' ? payload.diagnostic : (payload.diagnostic?.findings?.[0]?.type || payload.diagnostic?.status) }
          : {}),
        ...(payload.technical !== undefined ? { technical: payload.technical } : {}),
      },
      error: null,
    },
  }];
}

const workflowStatus = String(payload.workflow?.status || '').toLowerCase();
const instruction = typeof payload.instruction === 'string' ? payload.instruction.trim() : '';
const questionLegacy = typeof payload.question === 'string' ? payload.question.trim() : '';
const question = instruction || questionLegacy;

const findingType = payload.diagnostic?.findings?.[0]?.type;
const diagnosticLabel =
  typeof payload.diagnostic === 'string'
    ? payload.diagnostic
    : (findingType || payload.diagnostic?.status || payload.workflow?.currentStep || undefined);

let status;
if (workflowStatus === 'waiting_user' || workflowStatus === 'waiting') {
  status = 'WAITING_USER';
} else if (['completed', 'complete', 'resolved', 'done'].includes(workflowStatus)) {
  status = 'COMPLETED';
} else if (['escalated', 'failed', 'error', 'unresolvable'].includes(workflowStatus)) {
  status = 'ESCALATED';
} else if (question) {
  // Si el microservicio dejó instrucción al usuario, es WAITING_USER aunque falte workflow.status
  status = 'WAITING_USER';
} else if (payload.success === true) {
  status = 'COMPLETED';
} else {
  status = 'ESCALATED';
}

const result = {
  status,
  ...(status === 'WAITING_USER' && question ? { question } : {}),
  ...(diagnosticLabel !== undefined ? { diagnostic: diagnosticLabel } : {}),
  ...(payload.technical !== undefined ? { technical: payload.technical } : {}),
};

return [{ json: { success: true, result, error: null } }];

